// reveal + counters
function countUp(el){
 var to=+el.dataset.to, t0=null, d=1800;
 function step(t){ if(!t0) t0=t; var p=Math.min((t-t0)/d,1); el.textContent=Math.round(to*(1-Math.pow(1-p,3))); if(p<1) requestAnimationFrame(step); }
 requestAnimationFrame(step);
}
function setIdx(parent){ Array.prototype.forEach.call(parent.children,function(c,i){ c.style.setProperty("--i",i); }); }
document.querySelectorAll(".stag").forEach(setIdx);
var io=new IntersectionObserver(function(es){ es.forEach(function(e){
 if(e.isIntersecting){ e.target.classList.add("in"); e.target.querySelectorAll(".count").forEach(countUp); io.unobserve(e.target); }
}); },{threshold:.15});
document.querySelectorAll(".reveal").forEach(function(el){ io.observe(el); });

// hero particles
(function(){
 var cv=$("fx");
 if(!cv || window.matchMedia("(prefers-reduced-motion:reduce)").matches) return;
 var ctx=cv.getContext("2d"), W=0, H=0, dpr=Math.min(window.devicePixelRatio||1,2), P=[], running=false;
 var N = window.innerWidth<700 ? 14 : 30;
 function size(){ var r=cv.parentNode.getBoundingClientRect(); W=r.width; H=r.height; cv.width=W*dpr; cv.height=H*dpr; ctx.setTransform(dpr,0,0,dpr,0,0); }
 function mk(init){ var k=Math.random(); return {x:Math.random()*W,y:init?Math.random()*H:H+30,s:6+Math.random()*14,v:.25+Math.random()*.6,a:Math.random()*6.28,w:.01+Math.random()*.02,r:Math.random()*6.28,rv:(Math.random()-.5)*.02,c:k<.3?"#f0e62b":(k<.65?"#7dc242":"#3fb55a"),o:.25+Math.random()*.45,dot:Math.random()<.4}; }
 function leaf(p){ ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.r); ctx.globalAlpha=p.o; ctx.fillStyle=p.c; ctx.beginPath(); ctx.moveTo(0,-p.s); ctx.quadraticCurveTo(p.s*.8,-p.s*.2,0,p.s); ctx.quadraticCurveTo(-p.s*.8,-p.s*.2,0,-p.s); ctx.fill(); ctx.restore(); }
 function dot(p){ ctx.globalAlpha=p.o; ctx.fillStyle=p.c; ctx.beginPath(); ctx.arc(p.x,p.y,p.s*.2,0,6.28); ctx.fill(); }
 function tick(){
  if(!running) return;
  ctx.clearRect(0,0,W,H);
  for(var i=0;i<P.length;i++){ var p=P[i]; p.y-=p.v; p.a+=p.w; p.x+=Math.sin(p.a)*.5; p.r+=p.rv; if(p.dot) dot(p); else leaf(p); if(p.y<-30) P[i]=mk(false); }
  requestAnimationFrame(tick);
 }
 size(); for(var i=0;i<N;i++) P.push(mk(true));
 window.addEventListener("resize", size);
 new IntersectionObserver(function(es){ var on=es[0].isIntersecting; if(on&&!running){ running=true; tick(); } else if(!on){ running=false; } }).observe(cv);
})();

// hero mouse parallax
(function(){
 var hero=document.querySelector(".hero"), lg=$("heroLogo");
 if(!window.matchMedia("(pointer:fine)").matches) return;
 hero.addEventListener("pointermove",function(e){ var r=hero.getBoundingClientRect(); lg.style.setProperty("--px",((e.clientX-r.left)/r.width-.5).toFixed(3)); lg.style.setProperty("--py",((e.clientY-r.top)/r.height-.5).toFixed(3)); });
 hero.addEventListener("pointerleave",function(){ lg.style.setProperty("--px",0); lg.style.setProperty("--py",0); });
})();

// 3D tilt (delegated)
document.addEventListener("pointermove",function(e){
 if(e.pointerType!=="mouse") return;
 var el=e.target.closest&&e.target.closest(".tilt"); if(!el) return;
 var r=el.getBoundingClientRect(), x=(e.clientX-r.left)/r.width, y=(e.clientY-r.top)/r.height;
 el.style.setProperty("--mx",(x*100)+"%"); el.style.setProperty("--my",(y*100)+"%");
 el.style.transform="perspective(700px) rotateX("+((.5-y)*8)+"deg) rotateY("+((x-.5)*8)+"deg) translateY(-6px)";
});
document.addEventListener("pointerout",function(e){ var el=e.target.closest&&e.target.closest(".tilt"); if(el&&!el.contains(e.relatedTarget)) el.style.transform=""; });

// products
function loadLocal(){ try{ var a=JSON.parse(localStorage.getItem("mobidkom_products")||"[]"); return (Array.isArray(a)?a:[]).map(cleanProduct).filter(Boolean); }catch(e){ return []; } }
function saveLocal(l){ try{ localStorage.setItem("mobidkom_products",JSON.stringify(l)); }catch(e){} }
var activeCat="الكل";

function renderCats(){
 var all=PRODUCTS.concat(loadLocal()), box=$("cats"), items=[{n:"الكل",e:"🌿"}].concat(CATEGORIES);
 box.innerHTML="";
 items.forEach(function(c,i){
  var cnt=c.n==="الكل"?all.length:all.filter(function(p){return p.cat===c.n;}).length;
  var b=document.createElement("button");
  b.type="button"; b.className="cat"+(c.n===activeCat?" active":""); b.style.setProperty("--i",i);
  b.innerHTML='<em>'+cnt+'</em><span class="e">'+c.e+'</span><b>'+esc(c.n)+'</b>';
  b.onclick=function(){ activeCat=c.n; renderCats(); renderProducts(); };
  box.appendChild(b);
 });
}
function revAll(){ var a=ld("mb_revs",[]); return (Array.isArray(a)?a:[]).map(cleanRev).filter(Boolean); }
function revsFor(n){
 var seen={}, out=[];
 REVIEWS.map(function(r){ var c=Object.assign({},r,{status:"معتمد"}); return cleanRev(c); }).concat(revAll().filter(function(r){ return r.status==="معتمد"; })).forEach(function(r){ if(r&&r.p===n&&!seen[r.id]){ seen[r.id]=1; out.push(r); } });
 return out;
}
function stars(n){ n=Math.max(0,Math.min(5,Math.round(n))); return "★★★★★".slice(0,n)+"☆☆☆☆☆".slice(0,5-n); }
function rateHtml(p){
 var rv=revsFor(p.name), n=rv.length, avg=n?rv.reduce(function(s,r){ return s+r.s; },0)/n:0;
 return '<div class="rate">'+(n?'<span class="stars">'+stars(avg)+'</span> <small>'+avg.toFixed(1)+' ('+n+')</small>':'<small>لا تقييمات بعد</small>')+' <button type="button" class="rbtn" data-rate="'+esc(p.name)+'">قيّم / شوف التقييمات</button></div>';
}
function shows(p){ return p.pm==="show"&&p.price>0; }
function prHtml(p){ return shows(p)?'<span class="price"><b>'+fmt(p.price)+' جنيه</b></span>':'<span class="price">السعر: خاص، اطلبه على واتساب</span>'; }
function waBtn(p){ return shows(p)?'':'<a class="btn small" style="background:var(--g2)" target="_blank" rel="noopener" href="'+waLink("عايز أسأل عن سعر: "+p.name)+'">اطلب السعر على واتساب</a>'; }
function priceOf(n){ var p=PRODUCTS.concat(loadLocal()).filter(function(x){return x.name===n;})[0]; return (p&&shows(p))?p.price:0; }
function renderProducts(){
 var all=PRODUCTS.concat(loadLocal());
 var list=activeCat==="الكل"?all:all.filter(function(p){return p.cat===activeCat;});
 var g=$("grid"); g.innerHTML="";
 if(!list.length){ g.innerHTML='<div class="empty"><span class="e">🌱</span>هيتم إضافة منتجات هذا القسم قريبًا.</div>'; return; }
 list.forEach(function(p,i){
  var c=document.createElement("div"); c.className="product tilt"; c.style.setProperty("--i",i);
  var th=p.img?'<img src="'+esc(p.img)+'" alt="'+esc(p.name)+'">':'<span class="e">'+icon(p.cat)+'</span>';
  c.innerHTML='<div class="thumb">'+th+'</div><div class="pbody"><span class="tag">'+esc(p.cat)+'</span><h4>'+esc(p.name)+'</h4>'+rateHtml(p)+'<p>'+esc(p.desc||"")+'</p>'+prHtml(p)+'<button class="btn small" type="button" data-order="'+esc(p.name)+'">🛒 أضف للسلة</button>'+waBtn(p)+'</div>';
  g.appendChild(c);
 });
}
renderCats(); renderProducts();

// ===== أمان: تشفير كلمات السر + تنظيف البيانات + منع التخمين =====
var SUBTLE=(window.crypto&&window.crypto.subtle)||null;
function hex(b){ return Array.prototype.map.call(new Uint8Array(b),function(x){ return ("0"+x.toString(16)).slice(-2); }).join(""); }
function rnd(n){ var a=new Uint8Array(n); window.crypto.getRandomValues(a); return hex(a); }
function pbk(pw,salt){
 if(!SUBTLE) return Promise.resolve("L"+hsh(salt+pw));
 var en=new TextEncoder();
 return SUBTLE.importKey("raw",en.encode(pw),"PBKDF2",false,["deriveBits"]).then(function(k){ return SUBTLE.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:en.encode(salt),iterations:150000},k,256); }).then(hex);
}
function lockLeft(k){ var l=ld(k,{n:0,until:0}); return Math.max(0,Math.ceil((l.until-Date.now())/1000)); }
function lockFail(k){ var l=ld(k,{n:0,until:0}); l.n++; if(l.n>=5) l.until=Date.now()+Math.min(900000,30000*Math.pow(2,l.n-5)); sv(k,l); return l.n>=5; }
function lockOk(k){ sv(k,{n:0,until:0}); }
function sid(x){ x=String(x==null?"":x); return /^[A-Za-z0-9_-]{1,40}$/.test(x)?x:null; }
function dstr(x){ x=String(x); return /^\d{4}-\d{2}-\d{2}$/.test(x)?x:null; }
function numc(x){ x=parseFloat(x); return (isFinite(x)&&x>=0&&x<1e9)?x:0; }
function tx(x,n){ return String(x==null?"":x).replace(/[\u0000-\u001f]/g," ").slice(0,n); }
function cleanProduct(x){
 if(!x||typeof x!=="object") return null;
 var cats=CATEGORIES.map(function(c){return c.n;}); if(cats.indexOf(x.cat)<0||!tx(x.name,80).trim()) return null;
 var img=(typeof x.img==="string"&&x.img.length<700000&&/^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+\/=]+$/.test(x.img))?x.img:"";
 var pm=(x.pm==="show"&&numc(x.price)>0)?"show":"wa";
 return {name:tx(x.name,80),cat:x.cat,desc:tx(x.desc,300),img:img,pm:pm,price:pm==="show"?numc(x.price):0};
}
function cleanOrder(o){
 if(!o||typeof o!=="object"||!/^MB-[A-Z0-9]{3,10}$/.test(String(o.id))) return null;
 var items=(Array.isArray(o.items)?o.items:[]).slice(0,30).map(function(i){ return [tx(i&&i[0],80),Math.min(100000,numc(i&&i[1]))]; }).filter(function(i){ return i[0]&&i[1]>0; });
 if(!items.length) return null;
 return {id:o.id,total:numc(o.total),date:dstr(o.date)||todayStr(),name:tx(o.name,60),phone:String(o.phone||"").replace(/[^\d+]/g,"").slice(0,16),addr:tx(o.addr,200),note:tx(o.note,300),items:items,status:ST.indexOf(o.status)>=0?o.status:"جديد"};
}
function cleanInq(o){
 if(!o||typeof o!=="object"||!/^IQ-[A-Z0-9]{3,10}$/.test(String(o.id))) return null;
 var t=tx(o.text,300).trim(); if(!t) return null;
 return {id:o.id,date:dstr(o.date)||todayStr(),name:tx(o.name,60),phone:String(o.phone||"").replace(/[^\d+]/g,"").slice(0,16),text:t,status:o.status==="تم الرد"?"تم الرد":"جديد",reply:tx(o.reply,500)};
}
function cleanRev(o){
 if(!o||typeof o!=="object"||!/^RV-[A-Z0-9]{3,10}$/.test(String(o.id))) return null;
 var st=parseInt(o.s,10); if(!(st>=1&&st<=5)||!tx(o.p,80).trim()) return null;
 return {id:o.id,p:tx(o.p,80),s:st,n:tx(o.n,60),phone:String(o.phone||"").replace(/[^\d+]/g,"").slice(0,16),t:tx(o.t,300),d:dstr(o.d)||todayStr(),status:(o.status==="معتمد"||o.status==="مرفوض")?o.status:"جديد"};
}
function cleanRestore(d){
 var dropped=0;
 function map(a,f){ return (Array.isArray(a)?a:[]).map(function(x){ var r=null; try{ r=f(x); }catch(e){} if(!r) dropped++; return r; }).filter(Boolean); }
 var cats=ADMIN_CATS.concat(["سداد موردين"]);
 return {
  journal:map(d.journal,function(x){ var id=sid(x.id),dt=dstr(x.date); if(!id||!dt||(x.type!=="in"&&x.type!=="out")) return null; var o={id:id,date:dt,type:x.type,note:tx(x.note,200),amount:numc(x.amount)}; if(cats.indexOf(x.cat)>=0) o.cat=x.cat; return o; }),
  parties:map(d.parties,function(x){ var id=sid(x.id); if(!id||(x.kind!=="c"&&x.kind!=="s")||!tx(x.name,80).trim()) return null; return {id:id,name:tx(x.name,80),phone:tx(x.phone,20),kind:x.kind}; }),
  entries:map(d.entries,function(x){ var id=sid(x.id),pid=sid(x.pid),dt=dstr(x.date); if(!id||!pid||!dt||(x.type!=="charge"&&x.type!=="payment")) return null; var o={id:id,pid:pid,type:x.type,amount:numc(x.amount),note:tx(x.note,200),date:dt}; if(x.item) o.item=tx(x.item,160); if(numc(x.qty)>0) o.qty=numc(x.qty); if(numc(x.price)>0) o.price=numc(x.price); return o; }),
  stock:map(d.stock,function(x){ var id=sid(x.id); if(!id||!tx(x.name,80).trim()) return null; return {id:id,name:tx(x.name,80),qty:numc(x.qty),unit:tx(x.unit,12),min:numc(x.min)}; }),
  products:map(d.products,cleanProduct),
  orders:map(d.orders,cleanOrder),
  inq:map(d.inq,cleanInq),
  revs:map(d.revs,cleanRev),
  dropped:dropped
 };
}

// ===== لوحة الإدارة (البيانات بتتحفظ على المتصفح ده بس) =====
var KEYS={journal:"mb_journal",parties:"mb_parties",entries:"mb_entries",stock:"mb_stock",pin:"mb_pin"};
function ld(k,d){ try{ var v=JSON.parse(localStorage.getItem(k)); return v==null?d:v; }catch(e){ return d; } }
function sv(k,v){ try{ localStorage.setItem(k,JSON.stringify(v)); }catch(e){} }
function uid(){ return Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function pad(n){ return n<10?"0"+n:""+n; }
function todayStr(){ var d=new Date(); return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate()); }
function fmt(n){ return Number(n||0).toLocaleString("en-US",{maximumFractionDigits:2}); }
function waPhone(ph){ var d=String(ph||"").replace(/\D/g,""); if(!d) return ""; if(d.indexOf("00")===0) d=d.slice(2); else if(d.charAt(0)==="0") d="20"+d.slice(1); return d; }
function sumBy(a,t){ return a.filter(function(x){return x.type===t;}).reduce(function(s,x){return s+x.amount;},0); }

// فتح / قفل
var adm=$("adm");
var DEFPIN={s:"mobidkom-default",h:"60a90fb85ac6e22a9932af03d56340fe7edbc98624b251c2bc148bf33c55ae79",hl:"L"+hsh("mobidkom-default1234")};
function lock(){
 var has=true;
 $("admGate").hidden=false; $("admApp").hidden=true; $("admPin").value=""; $("admPin2").value=""; $("admPin2").hidden=has;
 $("admUnlock").textContent=has?"دخول":"إنشاء كلمة السر";
 $("admH").textContent=has?"دخول الإدارة":"إنشاء كلمة سر للإدارة";
 $("admP").textContent=has?"القسم ده خاص بفريق العمل. اكتب كلمة السر.":"أول مرة: اختار كلمة سر قوية (6 حروف أو أرقام على الأقل) وماتنساهاش. لو نسيتها لازم تمسح بيانات الموقع من المتصفح (وهتفقد البيانات)، فاعمل نسخة احتياطية.";
 $("admMsg").textContent="";
}
$("admOpen").onclick=function(){ lock(); adm.hidden=false; document.body.style.overflow="hidden"; setTimeout(function(){ $("admPin").focus(); },50); };
var idleT;
function closeAdm(){ adm.hidden=true; document.body.style.overflow=""; clearTimeout(idleT); lock(); }
function resetIdle(){ clearTimeout(idleT); idleT=setTimeout(function(){ if(!adm.hidden) closeAdm(); },600000); }
$("admClose").onclick=closeAdm;
["pointerdown","keydown"].forEach(function(ev){ adm.addEventListener(ev,function(){ if(!$("admApp").hidden) resetIdle(); }); });
function startAdmin(){ syncCustomers(); $("admGate").hidden=true; $("admApp").hidden=false; $("jDate").value=todayStr(); openTab("day"); if(typeof updBadge==="function") updBadge(); resetIdle(); }
function tryUnlock(){
 var rec=ld("mb_pin2",null)||DEFPIN, v=$("admPin").value, msg=$("admMsg"), left=lockLeft("mb_lock");
 if(left>0){ msg.textContent="محاولات غلط كتير. جرّب بعد "+left+" ثانية."; return; }
 if(!rec){
  if(v.length<6){ msg.textContent="كلمة السر لازم 6 حروف أو أرقام على الأقل."; return; }
  if(v!==$("admPin2").value){ msg.textContent="كلمتين السر مش متطابقتين."; return; }
  var s=rnd(16); pbk(v,s).then(function(h){ sv("mb_pin2",{s:s,h:h}); startAdmin(); }); return;
 }
 pbk(v,rec.s).then(function(h){
  if(h===rec.h||h===rec.hl){ lockOk("mb_lock"); startAdmin(); }
  else { msg.textContent=lockFail("mb_lock")?"اتقفل مؤقتًا بسبب محاولات غلط.":"كلمة السر غلط."; }
 });
}
$("admUnlock").onclick=tryUnlock;
$("admPin").onkeydown=function(e){ if(e.key==="Enter") tryUnlock(); };
$("admPin2").onkeydown=function(e){ if(e.key==="Enter") tryUnlock(); };


