function renderStock(){
 var s=ld(KEYS.stock,[]), box=$("sList"); box.innerHTML="";
 if(!s.length){ box.innerHTML='<p class="lead">المخزون فاضي. ضيف أول صنف.</p>'; return; }
 s.forEach(function(x){
  var low=x.qty<=x.min, r=document.createElement("div"); r.className="item"+(low?" low":"");
  r.innerHTML='<div class="top"><span><b>'+esc(x.name)+'</b>'+(low?'<span class="badge" style="background:#d94c4c;color:#fff">ناقص</span>':'')+'</span><span class="amt">'+fmt(x.qty)+' '+esc(x.unit)+'</span><span class="acts"><button type="button" data-a="dec" data-id="'+x.id+'">-1</button><button type="button" data-a="inc" data-id="'+x.id+'">+1</button><button type="button" data-a="set" data-id="'+x.id+'">تعديل الكمية</button><button class="d" type="button" data-a="del" data-id="'+x.id+'">حذف</button></span></div>';
  box.appendChild(r);
 });
}
$("sList").onclick=function(e){
 var b=e.target.closest("button"); if(!b) return;
 var s=ld(KEYS.stock,[]), x=s.filter(function(i){return i.id===b.dataset.id;})[0]; if(!x) return;
 var a=b.dataset.a;
 if(a==="inc") x.qty+=1; else if(a==="dec") x.qty=Math.max(0,x.qty-1);
 else if(a==="set"){ var v=parseFloat(prompt("الكمية الجديدة:",x.qty)); if(!(v>=0)) return; x.qty=v; }
 else if(a==="del"){ if(!confirm("حذف الصنف ده؟")) return; s=s.filter(function(i){return i.id!==x.id;}); }
 sv(KEYS.stock,s); renderStock();
};
$("sForm").onsubmit=function(e){
 e.preventDefault();
 var name=$("sName").value.trim(), qty=parseFloat($("sQty").value), min=parseFloat($("sMin").value);
 if(!name||!(qty>=0)) return;
 var s=ld(KEYS.stock,[]), x=s.filter(function(i){return i.name.toLowerCase()===name.toLowerCase();})[0];
 if(x){ x.qty+=qty; x.unit=$("sUnit").value; if(min>=0) x.min=min; } else s.push({id:uid(),name:name,qty:qty,unit:$("sUnit").value,min:min>=0?min:0});
 sv(KEYS.stock,s); this.reset(); $("sMin").value=5; renderStock();
};

