cmBody.onsubmit=function(e){
 e.preventDefault(); var id=e.target.id, msg=$("cmMsg"), us=ld("mb_users",{});
 if(id==="rgF"){
  var n=tx($("rgN").value.trim(),60), p=$("rgP").value.replace(/[^\d+]/g,"").slice(0,16), w=$("rgW").value;
  if(!n||p.length<8){ msg.textContent="اكتب الاسم ورقم تليفون صحيح."; return; }
  if(w.length<6){ msg.textContent="كلمة السر لازم 6 حروف أو أرقام على الأقل."; return; }
  if(us[p]){ msg.textContent="الرقم ده مسجّل قبل كده، سجّل دخول."; return; }
  var salt=rnd(16); pbk(w,salt).then(function(h){ us[p]={name:n,phone:p,s:salt,h2:h}; sv("mb_users",us); sv("mb_session",{name:n,phone:p}); renderCm(); });
 } else if(id==="lgF"){
  var p2=$("lgP").value.replace(/[^\d+]/g,""), u=us[p2], left=lockLeft("mb_clock"), pw=$("lgW").value;
  if(left>0){ msg.textContent="محاولات غلط كتير. جرّب بعد "+left+" ثانية."; return; }
  (u?(u.h2?pbk(pw,u.s).then(function(h){ return h===u.h2; }):Promise.resolve(u.h===hsh(pw))):Promise.resolve(false)).then(function(ok){
   if(!ok){ msg.textContent=lockFail("mb_clock")?"اتقفل مؤقتًا بسبب محاولات غلط.":"الرقم أو كلمة السر غلط (الحساب بيتحفظ على الجهاز اللي سجلت منه)."; return; }
   lockOk("mb_clock"); sv("mb_session",{name:u.name,phone:u.phone}); renderCm();
  });
 } else if(id==="rvF"){
  var s0=me(); if(!s0) return;
  if(!(cmStar>=1)){ msg.textContent="اختار عدد النجوم."; return; }
  var rt2=ld("mb_rrates",[]).filter(function(t){ return Date.now()-t<3600000; });
  if(rt2.length>=5){ msg.textContent="قيّمت منتجات كتير في ساعة. جرّب بعد شوية."; return; }
  var rs=ld("mb_revs",[]);
  if(rs.some(function(r){ return r.p===cmRate&&r.phone===s0.phone; })){ msg.textContent="انت قيّمت المنتج ده قبل كده."; return; }
  var rv2={id:"RV-"+Date.now().toString(36).toUpperCase().slice(-6),p:cmRate,s:cmStar,n:s0.name,phone:s0.phone,t:tx($("rvT").value.trim(),300),d:todayStr(),status:"جديد"};
  rs.push(rv2); sv("mb_revs",rs); rt2.push(Date.now()); sv("mb_rrates",rt2);
  var code3="MB3:"+btoa(unescape(encodeURIComponent(JSON.stringify(rv2))));
  window.open(waLink("تقييم جديد لمنتج: "+rv2.p+"\nالتقييم: "+rv2.s+"/5 ⭐\nالاسم: "+rv2.n+(rv2.t?"\nالتعليق: "+rv2.t:"")+"\nكود التقييم: "+code3),"_blank","noopener,noreferrer");
  cmStar=0; renderCm(); $("cmMsg").textContent="شكرًا لتقييمك! كمّل الإرسال من واتساب، والتقييم بيظهر بعد مراجعته.";
 } else if(id==="orF"){
  if($("orH")&&$("orH").value) return;
  var rt=ld("mb_orates",[]).filter(function(t){ return Date.now()-t<3600000; });
  if(rt.length>=5){ msg.textContent="عملت طلبات كتير في ساعة. جرّب بعد شوية أو كلمنا على واتساب."; return; }
  var s=me(), items=[]; document.querySelectorAll("#orows .orow").forEach(function(r){ var nm=r.querySelector(".oi").value.trim(), q=parseFloat(r.querySelector(".oq").value); if(nm&&q>0&&items.length<30) items.push([tx(nm,80),Math.min(q,100000)]); });
  if(!items.length){ msg.textContent="اكتب صنف واحد على الأقل."; return; }
  var o={id:"MB-"+Date.now().toString(36).toUpperCase().slice(-6),date:todayStr(),name:s.name,phone:s.phone,addr:tx($("orA").value.trim(),200),note:tx($("orN").value.trim(),300),items:items,total:Math.round(items.reduce(function(s,i){ return s+priceOf(i[0])*i[1]; },0)*100)/100,status:"جديد"};
  var all=ordersAll(); all.push(o); sv("mb_orders",all); setCart([]); rt.push(Date.now()); sv("mb_orates",rt);
  var code="MB1:"+btoa(unescape(encodeURIComponent(JSON.stringify(o))));
  var t="طلب جديد من موقع مبيدكم 🌿\nرقم الطلب: "+o.id+"\nالاسم: "+o.name+"\nالتليفون: "+o.phone+(o.addr?"\nالعنوان: "+o.addr:"")+"\nالأصناف:\n"+items.map(function(i,k){ return (k+1)+") "+i[0]+" × "+i[1]; }).join("\n")+(o.total>0?"\nالإجمالي (للأصناف المسعّرة): "+fmt(o.total)+" جنيه":"")+(o.note?"\nملاحظات: "+o.note:"")+"\nكود الطلب: "+code;
  window.open(waLink(t),"_blank","noopener,noreferrer"); cmView="account"; renderCm(); $("cmMsg").textContent="تم تجهيز طلبك. كمّل الإرسال من واتساب عشان يوصلنا.";
 }
};

