$("oSt").onchange=renderOrders;
$("oList").onclick=function(e){
 var b=e.target.closest("button"); if(!b) return; var all=ordersAll(), o=all.filter(function(x){return x.id===b.dataset.id;})[0]; if(!o) return; var a=b.dataset.a;
 if(a==="st"){ o.status=b.dataset.s; sv("mb_orders",all); }
 else if(a==="cust"){ upsertCustomer(o.name,o.phone); openTab("cust"); $("ac_q").value=o.phone||o.name; ACC.c(); return; }
 else if(a==="wa"){ window.open(waLink2(waPhone(o.phone),"أهلًا "+o.name+"، طلبك رقم "+o.id+" حالته: "+o.status+". شكرًا لتعاملك مع مبيدكم."),"_blank","noopener,noreferrer"); return; }
 else if(a==="del"){ if(!confirm("حذف الطلب ده؟")) return; all=all.filter(function(x){return x.id!==o.id;}); sv("mb_orders",all); }
 else if(a==="acc"){
  var amt=parseFloat(prompt("إجمالي الفاتورة بالجنيه:",o.total||"")); if(!(amt>0)) return;
  var ps=ld(KEYS.parties,[]), en=ld(KEYS.entries,[]), x=ps.filter(function(i){return i.kind==="c"&&(i.phone===o.phone||i.name===o.name);})[0];
  if(!x){ x={id:uid(),name:o.name,phone:o.phone,kind:"c"}; ps.push(x); }
  en.push({id:uid(),pid:x.id,type:"charge",amount:amt,note:"طلب "+o.id,item:o.items.map(function(i){return i[0]+" ×"+i[1];}).join("، "),date:todayStr()});
  sv(KEYS.parties,ps); sv(KEYS.entries,en); o.status="تم التسليم"; sv("mb_orders",all);
 }
 renderOrders();
};
$("oImpBtn").onclick=function(){
 var m=$("oImp").value.match(/MB1:([A-Za-z0-9+\/=]+)/), msg=$("oMsg");
 if(!m){ msg.textContent="مفيش كود طلب في النص."; return; }
 try{ var o=cleanOrder(JSON.parse(decodeURIComponent(escape(atob(m[1]))))); if(!o) throw 0;
  var all=ordersAll(); if(all.some(function(x){return x.id===o.id;})){ msg.textContent="الطلب ده مستورد قبل كده."; return; }
  all.push(o); sv("mb_orders",all); upsertCustomer(o.name,o.phone); $("oImp").value=""; msg.textContent="تم استيراد الطلب."; renderOrders();
 }catch(x){ msg.textContent="الكود تالف أو ناقص."; }
};

// ----- الاستفسارات -----
function inqAll(){ var a=ld("mb_inq",[]); return (Array.isArray(a)?a:[]).map(cleanInq).filter(Boolean); }
$("qF").onsubmit=function(e){
 e.preventDefault(); if($("qH").value) return;
 var msg=$("qMsg"), rt=ld("mb_irates",[]).filter(function(t){ return Date.now()-t<3600000; });
 if(rt.length>=5){ msg.textContent="بعتّ استفسارات كتير في ساعة. جرّب بعد شوية أو كلمنا على واتساب."; return; }
 var o={id:"IQ-"+Date.now().toString(36).toUpperCase().slice(-6),date:todayStr(),name:tx($("qN").value.trim(),60),phone:$("qP").value.replace(/[^\d+]/g,"").slice(0,16),text:tx($("qT").value.trim(),300),status:"جديد",reply:""};
 if(!o.name||o.phone.length<8||!o.text){ msg.textContent="اكتب الاسم ورقم تليفون صحيح والاستفسار."; return; }
 var all=ld("mb_inq",[]); all.push(o); sv("mb_inq",all); rt.push(Date.now()); sv("mb_irates",rt);
 var code="MB2:"+btoa(unescape(encodeURIComponent(JSON.stringify(o))));
 window.open(waLink("استفسار من موقع مبيدكم 💬\nالاسم: "+o.name+"\nالتليفون: "+o.phone+"\nالاستفسار: "+o.text+"\nكود الاستفسار: "+code),"_blank","noopener,noreferrer");
 msg.textContent="تم تجهيز استفسارك. كمّل الإرسال من واتساب عشان يوصلنا."; this.reset();
};
function renderInq(){
 updBadge(); var f=$("iSt").value, l=inqAll().filter(function(x){ return !f||x.status===f; }).reverse(), box=$("iList"); box.innerHTML="";
 if(!l.length){ box.innerHTML='<p class="lead">مفيش استفسارات.</p>'; return; }
 l.forEach(function(x){
  var r=document.createElement("div"); r.className="item"+(x.status==="جديد"?" low":"");
  r.innerHTML='<div class="top"><span><b>'+esc(x.name)+'</b><span class="badge" dir="ltr">'+esc(x.phone)+'</span><span class="badge">'+esc(x.status)+'</span></span><span>'+x.date+' · '+esc(x.id)+'</span></div><div style="margin:6px 0">❓ '+esc(x.text)+'</div>'+(x.reply?'<div class="notice">ردّك: '+esc(x.reply)+'</div>':'')+'<textarea rows="2" placeholder="اكتب ردّك هنا" style="margin:6px 0">'+esc(x.reply)+'</textarea><div class="acts"><button class="w" type="button" data-a="reply" data-id="'+x.id+'">رد على واتساب</button><button class="d" type="button" data-a="del" data-id="'+x.id+'">حذف</button></div>';
  box.appendChild(r);
 });
}
$("iSt").onchange=renderInq;
$("iList").onclick=function(e){
 var b=e.target.closest("button"); if(!b) return; var all=inqAll(), x=all.filter(function(i){ return i.id===b.dataset.id; })[0]; if(!x) return;
 if(b.dataset.a==="del"){ if(!confirm("حذف الاستفسار ده؟")) return; all=all.filter(function(i){ return i.id!==x.id; }); sv("mb_inq",all); }
 else if(b.dataset.a==="reply"){
  var t=tx(b.closest(".item").querySelector("textarea").value.trim(),500); if(!t){ alert("اكتب الرد الأول."); return; }
  x.reply=t; x.status="تم الرد"; sv("mb_inq",all);
  window.open(waLink2(waPhone(x.phone),"أهلًا "+x.name+"، بخصوص استفسارك: «"+x.text+"»\n"+t+"\n— مبيدكم"),"_blank","noopener,noreferrer");
 }
 renderInq();
};
$("iImpBtn").onclick=function(){
 var m=$("iImp").value.match(/MB2:([A-Za-z0-9+\/=]+)/), msg=$("iMsg");
 if(!m){ msg.textContent="مفيش كود استفسار في النص."; return; }
 try{ var o=cleanInq(JSON.parse(decodeURIComponent(escape(atob(m[1]))))); if(!o) throw 0;
  var all=inqAll(); if(all.some(function(x){ return x.id===o.id; })){ msg.textContent="الاستفسار ده مستورد قبل كده."; return; }
  all.push(o); sv("mb_inq",all); $("iImp").value=""; msg.textContent="تم استيراد الاستفسار."; renderInq();
 }catch(x){ msg.textContent="الكود تالف أو ناقص."; }
};

// ----- التقييمات في الإدارة -----
function renderRev(){
 updBadge(); var f=$("rSt").value, l=revAll().filter(function(x){ return !f||x.status===f; }).reverse(), box=$("rList"); box.innerHTML="";
 if(!l.length){ box.innerHTML='<p class="lead">مفيش تقييمات.</p>'; return; }
 l.forEach(function(x){
  var r=document.createElement("div"); r.className="item"+(x.status==="جديد"?" low":"");
  r.innerHTML='<div class="top"><span><b>'+esc(x.p)+'</b> <span class="stars">'+stars(x.s)+'</span><span class="badge">'+esc(x.status)+'</span></span><span>'+esc(x.n)+' · '+x.d+'</span></div>'+(x.t?'<div style="margin:6px 0">'+esc(x.t)+'</div>':'')+'<div class="acts"><button type="button" data-a="ok" data-id="'+x.id+'">اعتماد</button><button type="button" data-a="no" data-id="'+x.id+'">رفض</button><button class="d" type="button" data-a="del" data-id="'+x.id+'">حذف</button></div>';
  box.appendChild(r);
 });
}
$("rSt").onchange=renderRev;
$("rList").onclick=function(e){
 var b=e.target.closest("button"); if(!b) return; var all=revAll(), x=all.filter(function(i){ return i.id===b.dataset.id; })[0]; if(!x) return;
 if(b.dataset.a==="ok") x.status="معتمد"; else if(b.dataset.a==="no") x.status="مرفوض";
 else if(b.dataset.a==="del"){ if(!confirm("حذف التقييم ده؟")) return; all=all.filter(function(i){ return i.id!==x.id; }); }
 sv("mb_revs",all); renderRev(); renderProducts();
};
$("rImpBtn").onclick=function(){
 var m=$("rImp").value.match(/MB3:([A-Za-z0-9+\/=]+)/), msg=$("rMsg");
 if(!m){ msg.textContent="مفيش كود تقييم في النص."; return; }
 try{ var o=cleanRev(JSON.parse(decodeURIComponent(escape(atob(m[1]))))); if(!o) throw 0;
  var all=revAll(); if(all.some(function(x){ return x.id===o.id; })){ msg.textContent="التقييم ده مستورد قبل كده."; return; }
  o.status="جديد"; all.push(o); sv("mb_revs",all); $("rImp").value=""; msg.textContent="تم استيراد التقييم."; renderRev();
 }catch(x){ msg.textContent="الكود تالف أو ناقص."; }
};
$("rCopy").onclick=function(){
 var seen={}, out=[];
 REVIEWS.concat(revAll().filter(function(r){ return r.status==="معتمد"; })).forEach(function(r){ if(r&&r.id&&!seen[r.id]){ seen[r.id]=1; out.push({id:r.id,p:r.p,s:r.s,n:r.n,t:r.t,d:r.d}); } });
 copyText("var REVIEWS = "+JSON.stringify(out,null,1)+";",function(){ $("rMsg2").textContent="تم النسخ ("+out.length+" تقييم). ابعته لمطوّر الموقع."; },function(){ $("rMsg2").textContent="تعذّر النسخ."; });
};

